mapper.select:
SELECT * FROM ietm_data_module
WHERE status = '1'
  AND is_latest = '1'
  AND sns = #{sns}
  AND info_code = #{infoCode}
  AND (info_code_variant = #{infoCodeVariant}
       OR (info_code_variant IS NULL AND #{infoCodeVariant} IS NULL))
  AND (ietm_location_code = #{ietmLocationCode}
       OR (ietm_location_code IS NULL AND #{ietmLocationCode} IS NULL))
  AND language_iso_code = #{languageIsoCode}
  AND country_iso_code = #{countryIsoCode}

      AND id != #{excludeId}

FETCH FIRST 1 ROWS ONLY

SELECT id, project_id, sns, info_code, info_code_variant, ietm_location_code,
       dmc_code, issue_no, in_work, version_type, issue_type, is_latest, status,
       language_iso_code, country_iso_code, dm_content,
       checkout_user, checkout_time, tech_name, info_name,
       issue_date, create_by, create_time, update_time
FROM ietm_data_module
WHERE status = '1'
  AND sns = #{sns}
  AND info_code = #{infoCode}
  AND (info_code_variant = #{infoCodeVariant}
       OR (info_code_variant IS NULL AND #{infoCodeVariant} IS NULL))

  AND project_id = #{projectId}


  AND ietm_location_code = #{ietmLocationCode}


  AND version_type = '1'

ORDER BY CAST(issue_no AS NUMBER) DESC, CAST(in_work AS NUMBER) DESC

SELECT t1.id, t1.project_id, t1.project_name, t1.sns, t1.info_code, t1.info_code_variant, t1.ietm_location_code, t1.originator, t1.originator_name, t1.issue_no, t1.in_work, t1.version_type, t1.issue_type, t1.tech_name, t1.info_name, t1.cm_node_id, t1.cm_node_name, t1.cm_node_path, t1.is_latest, t1.status, t1.checkout_user, t1.checkout_time, t1.checkout_dm_id, t1.workflow_instance_id, t1.workflow_status, t1.dmc_code, t1.create_time, t1.update_time, -- 列表/详情展示所需字段（DM类型/密级/签发日期/语言/国家/责任单位） t1.dm_type, t1.security, t1.issue_date, t1.language_iso_code, t1.country_iso_code, t1.rpc, t1.rpc_name, -- 从流程视图获取动态字段 v.activityalias_ AS activityalias_, -- 流程当前步骤（实时计算） v.currenthandler_ AS currenthandler_ -- 当前待办人（实时） FROM ietm_data_module t1 LEFT JOIN v_wf_instance v ON t1.id = v.formid_ WHERE t1.status = '1' AND t1.is_latest = '1'
AND t1.project_id = #{projectId}
AND t1.cm_node_id IN ( SELECT id FROM ietm_project_configuration_management START WITH id = #{cmNodeId} CONNECT BY PRIOR id = pid )
AND t1.cm_node_id = #{cmNodeId}
ORDER BY t1.create_time DESC

SELECT dm_content
FROM ietm_data_module
WHERE id = #{id}
